import sys
MOD=998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    values = data[1:]

    factors = []
    for x in values:
        d = {}
        q = 2
        while q * q <= x:
            while x % q == 0:
                d[q] = d.get(q, 0) + 1
                x //= q
            q += 1
        if x > 1:
            d[x] = d.get(x, 0) + 1
        factors.append(d)

    answer = 1
    primes = set(p for d in factors for p in d)
    for p in primes:
        # h is the current valuation minus the minimum valuation so far;
        # dp[h] sums p^(sum of normalized valuations so far).
        dp = {0: 1}
        power_cache = {0: 1}

        def p_power(k):
            if k not in power_cache:
                power_cache[k] = pow(p, k, MOD)
            return power_cache[k]

        for i in range(1, n):
            e = factors[i - 1].get(p, 0)
            nxt = {}
            for h, ways in dp.items():
                if e == 0:
                    nxt[h] = (nxt.get(h, 0) + ways * p_power(h)) % MOD
                    continue

                # The valuation difference can be +e or -e.
                up = h + e
                nxt[up] = (nxt.get(up, 0) + ways * p_power(up)) % MOD

                if h >= e:
                    down = h - e
                    nxt[down] = (nxt.get(down, 0) + ways * p_power(down)) % MOD
                else:
                    # A new minimum is reached: all i previous heights
                    # increase by e-h, while the new height is zero.
                    nxt[0] = (nxt.get(0, 0) + ways * pow(p, i * (e - h), MOD)) % MOD
            dp = nxt

        answer = answer * (sum(dp.values()) % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    solve()

