def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[:2]
    processes = []
    pos = 2
    for _ in range(n):
        a, p, b, q = data[pos:pos + 4]
        pos += 4
        processes.append((a, p, b, q))

    def min_cost(k, a, p, b, q):
        # For a fixed x modulo b, shifting x by b changes the
        # required number of T machines by exactly -a. Thus cost is
        # linear along each such sequence, and its minimum is at an end.
        xmax = (k + a - 1) // a
        best = 10**30
        ranges = ((0, min(xmax, b - 1)), (max(0, xmax - b + 1), xmax))
        for left, right in ranges:
            for x in range(left, right + 1):
                y = max(0, (k - a * x + b - 1) // b)
                best = min(best, x * p + y * q)
        return best

    def feasible(k):
        total = 0
        for a, p, b, q in processes:
            total += min_cost(k, a, p, b, q)
            if total > budget:
                return False
        return True

    low, high = 0, 100 * budget + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

