from math import comb

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n = len(s)
        good = [False] * (n + 1)

        # A number with c set bits takes one operation to become c, then
        # the number of operations needed to reduce c to 1.
        for c in range(1, n + 1):
            x = c
            steps = 0
            while x != 1:
                x = x.bit_count()
                steps += 1
            good[c] = steps + 1 <= k

        ans = 0
        for c in range(1, n + 1):
            if not good[c]:
                continue
            used = 0
            ways = 0
            for i, ch in enumerate(s):
                rem = n - i - 1
                if ch == '1':
                    need = c - used
                    if 0 <= need <= rem:
                        ways += comb(rem, need)
                    used += 1
            ans += ways

        return ans % 1_000_000_007

